"use client";
import { useEffect, useRef, useState } from "react";
export function AnimatedCounter({value,suffix}:{value:number;suffix?:string}) {
 const ref=useRef<HTMLSpanElement>(null);
 const [display,setDisplay]=useState(value);
 const [started,setStarted]=useState(false);
 useEffect(()=>{
  const el=ref.current; if(!el) return;
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const io=new IntersectionObserver(([entry])=>{ if(entry.isIntersecting && !started){ setStarted(true); setDisplay(0); const start=performance.now(); const duration=1000; const tick=(now)=>{ const p=Math.min(1,(now-start)/duration); setDisplay(Math.floor(p*value)); if(p<1) requestAnimationFrame(tick); else setDisplay(value);}; requestAnimationFrame(tick); io.disconnect(); } },{threshold:0.4});
  io.observe(el); return ()=>io.disconnect();
 },[value,started]);
 return <span ref={ref}>{display}{suffix}</span>
}
```
